'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import {
  CalendarDays, ChevronDown, ChevronLeft, ChevronRight, ChevronUp,
  ClipboardList, Download, GripVertical, ImagePlus, Mic, MicOff,
  MoreHorizontal, RefreshCw, Settings, Trash2, Users, X,
} from 'lucide-react';
import { Checkbox } from '@/components/ui/checkbox';
import { parseInfoDump, type ParsedInfoTask } from '@/lib/info-dump';
import { recurringMovePlan } from '@/lib/domain';

type View = 'tasks' | 'calendar' | 'students' | 'settings';
type Role = 'ADVISOR' | 'STUDENT';
type Source = 'Personal' | 'Advisor' | 'Canvas' | 'Recurring';
type Priority = 'Low' | 'Normal' | 'High';
type Task = {
  id: string; owner: string; title: string; due: string | null; source: Source;
  status: 'TODO' | 'COMPLETED'; completedAt: string | null; estimatedMinutes: number;
  priority: Priority; scheduledStart: string | null; recurrence?: 'WEEKLY' | null;
  recurrenceDays?: number[]; recurrenceExceptions?: string[];
};
type ProposalTask = ParsedInfoTask & { selected: boolean };
type SectionName = 'Today'|'Upcoming'|'No date'|'Completed'|'Overdue';
type CalendarTaskDraft = Pick<Task,'title'|'owner'|'scheduledStart'|'estimatedMinutes'|'recurrence'|'recurrenceDays'|'priority'>;
type SpeechResultEvent = { resultIndex: number; results: ArrayLike<{ 0: { transcript: string } }> };
type SpeechRecognitionInstance = { continuous: boolean; interimResults: boolean; lang: string; onresult: (event: SpeechResultEvent) => void; onend: () => void; onerror: () => void; start: () => void; stop: () => void };
type SpeechRecognitionConstructor = new () => SpeechRecognitionInstance;

const students = ['Sarah Johnson', 'Michael Smith', 'Jake Brown', 'Emily Jones'];
const owners = ['Alex Advisor', ...students];
const defaultSectionOrder: SectionName[] = ['Today','Upcoming','No date','Completed','Overdue'];
const twelveHours = 12 * 60 * 60 * 1000;
const repeatDayLabels = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const repeatDayOrder = [1,2,3,4,5,6,0];
const isoAt = (offsetDays: number, hour: number, minute = 0) => {
  const d = new Date(); d.setHours(hour, minute, 0, 0); d.setDate(d.getDate() + offsetDays); return d.toISOString();
};
const seed: Task[] = [
  { id:'1', owner:'Alex Advisor', title:'Meet with Sarah', due:isoAt(0,9,30), source:'Personal', status:'TODO', completedAt:null, estimatedMinutes:30, priority:'Normal', scheduledStart:isoAt(0,9,30), recurrence:null },
  { id:'2', owner:'Sarah Johnson', title:'Register for Biology', due:isoAt(2,17), source:'Advisor', status:'TODO', completedAt:null, estimatedMinutes:30, priority:'High', scheduledStart:null, recurrence:null },
  { id:'3', owner:'Sarah Johnson', title:'Biology Chapter 4', due:isoAt(0,23,59), source:'Canvas', status:'TODO', completedAt:null, estimatedMinutes:45, priority:'Normal', scheduledStart:null, recurrence:null },
  { id:'4', owner:'Alex Advisor', title:'Review Michael’s schedule', due:null, source:'Personal', status:'TODO', completedAt:null, estimatedMinutes:30, priority:'Normal', scheduledStart:null, recurrence:null },
  { id:'5', owner:'Alex Advisor', title:'Send registration email', due:null, source:'Personal', status:'COMPLETED', completedAt:new Date(Date.now()-2*60*60*1000).toISOString(), estimatedMinutes:30, priority:'Normal', scheduledStart:null, recurrence:null },
  { id:'6', owner:'Michael Smith', title:'Submit chemistry worksheet', due:isoAt(-1,17), source:'Canvas', status:'TODO', completedAt:null, estimatedMinutes:45, priority:'High', scheduledStart:null, recurrence:null },
  { id:'7', owner:'Alex Advisor', title:'Weekly caseload review', due:null, source:'Recurring', status:'TODO', completedAt:null, estimatedMinutes:30, priority:'Low', scheduledStart:isoAt(3,11), recurrence:'WEEKLY' },
];
const nav = [[ClipboardList,'tasks','Tasks'],[CalendarDays,'calendar','Calendar'],[Users,'students','Students'],[Settings,'settings','Settings']] as const;
const dayKey = (d: Date | string) => new Date(d).toLocaleDateString('en-CA');
const sameDay = (a: Date | string, b: Date | string) => dayKey(a) === dayKey(b);
const fmtDate = (value: string | null) => value ? new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date(value)) : '';
const fmtTime = (value: string | null) => value ? new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(value)) : '';
const startOfWeek = (value: Date) => { const d=new Date(value); const day=d.getDay(); d.setDate(d.getDate()-(day===0?6:day-1)); d.setHours(0,0,0,0); return d; };
const toLocalInput = (iso: string | null) => iso ? new Date(new Date(iso).getTime()-new Date(iso).getTimezoneOffset()*60000).toISOString().slice(0,16) : '';
const recentCompletion = (task: Task, now = Date.now()) => task.status === 'TODO' || (!!task.completedAt && now - new Date(task.completedAt).getTime() < twelveHours);
const recurrenceDaysFor = (task: Pick<Task,'scheduledStart'|'recurrenceDays'>) => task.recurrenceDays?.length ? task.recurrenceDays : task.scheduledStart ? [new Date(task.scheduledStart).getDay()] : [];
const occursOn = (task: Task, day: Date) => !!task.scheduledStart && !task.recurrenceExceptions?.includes(dayKey(day)) && (task.recurrence === 'WEEKLY' ? recurrenceDaysFor(task).includes(day.getDay()) : sameDay(task.scheduledStart, day));
const timeRange = (start: string | null, minutes: number) => {
  if (!start) return '';
  const end=new Date(new Date(start).getTime()+minutes*60_000);
  return `${fmtTime(start)}–${fmtTime(end.toISOString())}`;
};
const nextTaskDate = (task: Task, now = new Date()) => {
  if (!task.recurrence || !task.scheduledStart) return task.due ?? task.scheduledStart;
  const base = new Date(task.scheduledStart), next = new Date(now);
  next.setHours(base.getHours(), base.getMinutes(), 0, 0);
  const days=recurrenceDaysFor(task);
  for(let distance=0;distance<8;distance++){const candidate=new Date(next);candidate.setDate(candidate.getDate()+distance);if(days.includes(candidate.getDay())&&candidate>=now&&!task.recurrenceExceptions?.includes(dayKey(candidate)))return candidate.toISOString()}
  return next.toISOString();
};
const repeatSummary=(task:Pick<Task,'recurrence'|'recurrenceDays'|'scheduledStart'>)=>task.recurrence?recurrenceDaysFor(task).length===7?'daily':recurrenceDaysFor(task).map(day=>repeatDayLabels[day]).join(', '):'';

export default function Home() {
  const [view,setView]=useState<View>('tasks');
  const [role,setRole]=useState<Role>('ADVISOR');
  const [scope,setScope]=useState('ALL');
  const [tasks,setTasks]=useState<Task[]>(seed);
  const [filter,setFilter]=useState('All');
  const [sectionOrder,setSectionOrder]=useState<SectionName[]>(defaultSectionOrder);
  const [editing,setEditing]=useState<Task|null>(null);
  const [undo,setUndo]=useState<Task|null>(null);
  const [notes,setNotes]=useState('');
  const [proposal,setProposal]=useState<ProposalTask[]>([]);
  const [lastSync,setLastSync]=useState('Not yet synced');
  const dumpRef=useRef<HTMLTextAreaElement>(null);

  useEffect(()=>{ const saved=localStorage.getItem('torgy-tasks-v1'); if(saved) queueMicrotask(()=>{try{const parsed=JSON.parse(saved) as Task[];setTasks(parsed.filter(task=>recentCompletion(task)))}catch{}}); },[]);
  useEffect(()=>localStorage.setItem('torgy-tasks-v1',JSON.stringify(tasks)),[tasks]);
  useEffect(()=>{const saved=localStorage.getItem('torgy-section-order-v1');if(saved)queueMicrotask(()=>{try{const parsed=JSON.parse(saved) as SectionName[];if(parsed.length===defaultSectionOrder.length)setSectionOrder(parsed)}catch{}})},[]);
  useEffect(()=>localStorage.setItem('torgy-section-order-v1',JSON.stringify(sectionOrder)),[sectionOrder]);
  useEffect(()=>{const timer=setInterval(()=>setTasks(current=>current.filter(task=>recentCompletion(task))),60_000);return()=>clearInterval(timer)},[]);
  useEffect(()=>{ const keys=(e:KeyboardEvent)=>{ if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='n'){e.preventDefault();setView('tasks');setTimeout(()=>dumpRef.current?.focus(),0)} }; addEventListener('keydown',keys); return()=>removeEventListener('keydown',keys); },[]);

  const scopeTasks=useMemo(()=>tasks.filter(task=>{
    if(role==='STUDENT') return task.owner==='Sarah Johnson';
    return scope==='ALL'||task.owner===scope;
  }),[tasks,role,scope]);
  const visible=useMemo(()=>scopeTasks.filter(task=>recentCompletion(task)&&(
    filter==='All'||filter===task.source||filter==='Completed'&&task.status==='COMPLETED'||filter==='Overdue'&&!!nextTaskDate(task)&&new Date(nextTaskDate(task)!)<new Date()&&task.status==='TODO'
  )),[scopeTasks,filter]);
  const scopeLabel=role==='STUDENT'?'Sarah Johnson':scope==='ALL'?'All work':scope;
  const contextOwners=useMemo(()=>role==='STUDENT'?['Sarah Johnson']:scope==='ALL'?owners:[scope],[role,scope]);

  function toggle(task:Task){ const complete=task.status==='TODO'; setTasks(current=>current.map(item=>item.id===task.id?{...item,status:complete?'COMPLETED':'TODO',completedAt:complete?new Date().toISOString():null}:item)); if(complete){setUndo(task);setTimeout(()=>setUndo(null),5000)} }
  function addProposal(){
    const additions=proposal.filter(item=>item.selected&&item.title.trim()).map(item=>({
      id:crypto.randomUUID(), owner:item.person, title:item.title, due:item.scheduledStart,
      source:(item.recurrence?'Recurring':item.person==='Alex Advisor'?'Personal':'Advisor') as Source,
      status:'TODO' as const, completedAt:null, estimatedMinutes:item.estimatedMinutes,
      priority:item.priority, scheduledStart:item.scheduledStart, recurrence:item.recurrence,recurrenceDays:item.recurrenceDays,
    }));
    setTasks(current=>[...additions,...current]);setProposal([]);setNotes('');
  }
  function saveTask(next:Task){ setTasks(current=>current.map(task=>task.id===next.id?next:task)); setEditing(null); }
  function deleteTask(id:string){ setTasks(current=>current.filter(task=>task.id!==id)); setEditing(null); }
  function updateTask(next:Task){setTasks(current=>current.map(task=>task.id===next.id?next:task))}
  function addCalendarTask(draft:CalendarTaskDraft){setTasks(current=>[{id:crypto.randomUUID(),...draft,due:draft.scheduledStart,source:draft.recurrence?'Recurring':draft.owner==='Alex Advisor'?'Personal':'Advisor',status:'TODO',completedAt:null},...current])}
  function moveSection(label:SectionName,target:SectionName){setSectionOrder(current=>{const from=current.indexOf(label),to=current.indexOf(target);if(from<0||to<0||from===to)return current;const copy=[...current];copy.splice(from,1);copy.splice(to,0,label);return copy})}

  return <main className="min-h-screen bg-background text-foreground">
    <header className="sticky top-0 z-30 border-b bg-background/95 backdrop-blur"><div className="flex h-14 w-full items-center gap-3 px-4 lg:px-6">
      <p className="mr-auto text-base font-semibold">Torgy</p>
      <select aria-label="Switch role" value={role} onChange={e=>{const next=e.target.value as Role;setRole(next);setScope(next==='STUDENT'?'Sarah Johnson':'ALL');setView('tasks')}} className="rounded-lg border bg-card px-2 py-2 text-xs"><option value="ADVISOR">Advisor view</option><option value="STUDENT">Student view · Sarah</option></select>
    </div></header>
    <div className="grid w-full lg:grid-cols-[220px_minmax(0,1fr)]">
      <nav className="fixed inset-x-0 bottom-0 z-30 flex justify-around border-t bg-background p-2 lg:static lg:block lg:min-h-[calc(100vh-56px)] lg:border-r lg:border-t-0 lg:p-4" aria-label="Primary">
        {nav.map(([Icon,id,label])=>role==='STUDENT'&&id==='students'?null:<button key={id} onClick={()=>{setView(id);if(id==='tasks'&&role==='ADVISOR')setScope('ALL')}} aria-label={label} className={`flex items-center gap-2 rounded-lg px-3 py-2.5 text-xs lg:mb-1 lg:w-full lg:text-sm ${view===id?'bg-primary text-primary-foreground':'text-muted-foreground hover:bg-muted'}`}><Icon className="size-4"/><span className="hidden sm:inline">{label}</span></button>)}
      </nav>
      <section className="min-w-0 px-4 py-5 pb-24 sm:px-6 lg:px-8 lg:py-6">
        {view==='tasks'&&<TasksView name={scopeLabel} tasks={visible} filter={filter} setFilter={setFilter} toggle={toggle} edit={setEditing} remove={deleteTask} notes={notes} setNotes={setNotes} proposal={proposal} setProposal={setProposal} addProposal={addProposal} dumpRef={dumpRef} sectionOrder={sectionOrder} moveSection={moveSection} allowedOwners={contextOwners}/>}
        {view==='students'&&<StudentsView tasks={tasks} open={name=>{setScope(name);setView('tasks')}}/>}
        {view==='calendar'&&<CalendarView tasks={scopeTasks.filter(recentCompletion)} update={updateTask} edit={setEditing} create={addCalendarTask} defaultOwner={contextOwners[0]} allowedOwners={contextOwners}/>}
        {view==='settings'&&<SettingsView lastSync={lastSync} sync={()=>setLastSync(new Date().toLocaleTimeString())} tasks={tasks}/>} 
      </section>
    </div>
    {editing&&<TaskEditor task={editing} allowedOwners={contextOwners} save={saveTask} remove={deleteTask} close={()=>setEditing(null)}/>}
    {undo&&<output className="fixed bottom-20 left-1/2 z-50 flex -translate-x-1/2 items-center gap-4 rounded-lg border bg-card px-4 py-3 text-sm shadow-lg lg:bottom-6">Task completed<button onClick={()=>{setTasks(current=>current.map(task=>task.id===undo.id?{...task,status:'TODO',completedAt:null}:task));setUndo(null)}} className="font-semibold underline">Undo</button></output>}
  </main>;
}

function TasksView({name,tasks,filter,setFilter,toggle,edit,remove,notes,setNotes,proposal,setProposal,addProposal,dumpRef,sectionOrder,moveSection,allowedOwners}:{name:string;tasks:Task[];filter:string;setFilter:(value:string)=>void;toggle:(task:Task)=>void;edit:(task:Task)=>void;remove:(id:string)=>void;notes:string;setNotes:(value:string)=>void;proposal:ProposalTask[];setProposal:React.Dispatch<React.SetStateAction<ProposalTask[]>>;addProposal:()=>void;dumpRef:React.RefObject<HTMLTextAreaElement|null>;sectionOrder:SectionName[];moveSection:(label:SectionName,target:SectionName)=>void;allowedOwners:string[]}){
  const [dragging,setDragging]=useState<SectionName|null>(null);
  const open=tasks.filter(task=>task.status==='TODO');
  const completed=tasks.filter(task=>task.status==='COMPLETED'&&recentCompletion(task));
  const dated=(task:Task)=>nextTaskDate(task);
  const sections:Record<SectionName,Task[]>={
    Today:open.filter(task=>dated(task)&&sameDay(dated(task)!,new Date())&&(task.recurrence||new Date(dated(task)!)>=new Date())),
    Upcoming:open.filter(task=>dated(task)&&!sameDay(dated(task)!,new Date())&&new Date(dated(task)!)>=new Date()),
    'No date':open.filter(task=>!dated(task)), Completed:completed,
    Overdue:open.filter(task=>dated(task)&&new Date(dated(task)!)<new Date()&&!task.recurrence),
  };
  return <div className="w-full"><div className="mb-3 flex items-center gap-3"><p className="mr-auto text-xs font-semibold uppercase tracking-[.14em] text-muted-foreground">{new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date())}</p><select aria-label="Filter tasks" value={filter} onChange={e=>setFilter(e.target.value)} className="h-10 rounded-lg border bg-card px-3 text-sm"><option>All</option><option>Advisor</option><option>Canvas</option><option>Recurring</option><option>Overdue</option><option>Completed</option></select></div>
    <InfoDump notes={notes} setNotes={setNotes} proposal={proposal} setProposal={setProposal} addProposal={addProposal} dumpRef={dumpRef} allowedOwners={allowedOwners}/>
    <p className="mt-3 flex items-center gap-1.5 text-xs text-muted-foreground"><GripVertical className="size-3.5"/>Drag a section heading to place it where you want.</p>
    <div className="mt-2 grid items-start gap-x-5 lg:grid-cols-2 2xl:grid-cols-3">{sectionOrder.map(label=>{const items=sections[label];return items.length?<TaskGroup key={label} section={label} label={label==='Completed'?'Completed · last 12 hours':label} tasks={items} toggle={toggle} edit={edit} remove={remove} showOwner={name==='All work'} dragging={dragging===label} onDragStart={()=>setDragging(label)} onDragEnd={()=>setDragging(null)} onDrop={source=>{moveSection(source,label);setDragging(null)}}/>:null})}</div>
  </div>;
}

function DateTimeControl({label,value,onChange,allDay=false}:{label:string;value:string|null;onChange:(value:string|null)=>void;allDay?:boolean}){
  const local=toLocalInput(value),dateValue=local.slice(0,10),timeValue=local.slice(11,16)||'09:00';
  const combine=(date:string,time:string)=>date?new Date(`${date}T${time||'09:00'}`).toISOString():null;
  const step=(minutes:number)=>{const base=value?new Date(value):new Date(`${dateValue||dayKey(new Date())}T${timeValue}`);base.setMinutes(base.getMinutes()+minutes);onChange(base.toISOString())};
  return <fieldset className="min-w-0"><legend className="mb-1 text-[11px] font-medium text-muted-foreground">{label}</legend><div className={`grid gap-1.5 ${allDay?'grid-cols-1':'grid-cols-[minmax(118px,1fr)_minmax(104px,1fr)_28px]'}`}><input aria-label={`${label} date`} type="date" value={dateValue} onChange={event=>onChange(combine(event.target.value,timeValue))} className="h-9 min-w-0 rounded-lg border bg-card px-2 text-xs"/>{!allDay&&<><input aria-label={`${label} time`} type="time" step="1800" value={timeValue} onChange={event=>onChange(combine(dateValue||dayKey(new Date()),event.target.value))} className="h-9 min-w-0 rounded-lg border bg-card px-2 text-xs"/><span className="grid h-9 grid-rows-2 overflow-hidden rounded-lg border bg-card"><button type="button" onClick={()=>step(30)} aria-label={`Move ${label.toLowerCase()} time later by 30 minutes`} title="30 minutes later" className="grid place-items-center border-b hover:bg-muted"><ChevronUp className="size-3"/></button><button type="button" onClick={()=>step(-30)} aria-label={`Move ${label.toLowerCase()} time earlier by 30 minutes`} title="30 minutes earlier" className="grid place-items-center hover:bg-muted"><ChevronDown className="size-3"/></button></span></>}</div></fieldset>;
}

function RepeatDays({value,start,onChange}:{value:number[]|undefined;start:string|null;onChange:(days:number[])=>void}){
  const selected=value?.length?value:start?[new Date(start).getDay()]:[new Date().getDay()];
  return <div className="flex flex-wrap gap-1" aria-label="Repeat days">{repeatDayOrder.map(day=>{const active=selected.includes(day);return <button type="button" key={day} aria-pressed={active} aria-label={`Repeat on ${new Intl.DateTimeFormat(undefined,{weekday:'long'}).format(new Date(2026,7,23+day))}`} onClick={()=>{const next=active?selected.filter(value=>value!==day):[...selected,day];if(next.length)onChange(next.sort())}} className={`min-w-9 rounded-lg border px-1.5 py-1.5 text-xs ${active?'bg-primary text-primary-foreground':'bg-card text-muted-foreground hover:bg-muted'}`}>{repeatDayLabels[day]}</button>})}</div>;
}

function InfoDump({notes,setNotes,proposal,setProposal,addProposal,dumpRef,allowedOwners}:{notes:string;setNotes:(value:string)=>void;proposal:ProposalTask[];setProposal:React.Dispatch<React.SetStateAction<ProposalTask[]>>;addProposal:()=>void;dumpRef:React.RefObject<HTMLTextAreaElement|null>;allowedOwners:string[]}){
  const [listening,setListening]=useState(false),[speechReady,setSpeechReady]=useState(false);
  const speechRef=useRef<SpeechRecognitionInstance|null>(null),singleOwner=allowedOwners.length===1?allowedOwners[0]:null;
  const update=(index:number,change:Partial<ProposalTask>)=>setProposal(current=>current.map((item,itemIndex)=>itemIndex===index?{...item,...change}:item));
  const resize=()=>{const area=dumpRef.current;if(!area)return;area.style.height='auto';area.style.height=`${Math.max(68,area.scrollHeight)}px`};
  useEffect(()=>{const browserWindow=window as typeof window&{SpeechRecognition?:SpeechRecognitionConstructor;webkitSpeechRecognition?:SpeechRecognitionConstructor};setSpeechReady(!!(browserWindow.SpeechRecognition||browserWindow.webkitSpeechRecognition));queueMicrotask(resize);return()=>speechRef.current?.stop()},[]);
  useEffect(()=>{queueMicrotask(resize)},[notes]);
  useEffect(()=>{const value=notes.trim();if(!value){setProposal([]);return}const timer=setTimeout(()=>{const people=allowedOwners.filter(owner=>owner!=='Alex Advisor'),personalOwner=allowedOwners.includes('Alex Advisor')?'Alex Advisor':allowedOwners[0];setProposal(parseInfoDump(value,people,personalOwner).map(item=>({...item,selected:true})))},400);return()=>clearTimeout(timer)},[notes,allowedOwners,setProposal]);
  const toggleSpeech=()=>{if(listening){speechRef.current?.stop();setListening(false);return}const browserWindow=window as typeof window&{SpeechRecognition?:SpeechRecognitionConstructor;webkitSpeechRecognition?:SpeechRecognitionConstructor},Recognition=browserWindow.SpeechRecognition||browserWindow.webkitSpeechRecognition;if(!Recognition)return;const recognition=new Recognition();recognition.continuous=false;recognition.interimResults=false;recognition.lang='en-US';recognition.onresult=event=>{let transcript='';for(let index=event.resultIndex;index<event.results.length;index++)transcript+=event.results[index][0].transcript;setNotes(notes.trim()?`${notes.trim()} ${transcript.trim()}`:transcript.trim())};recognition.onend=()=>setListening(false);recognition.onerror=()=>setListening(false);speechRef.current=recognition;recognition.start();setListening(true)};
  return <section><textarea ref={dumpRef} value={notes} onChange={e=>{setNotes(e.target.value);queueMicrotask(resize)}} rows={2} spellCheck autoCorrect="on" autoCapitalize="sentences" placeholder={'Info dump\nType or speak naturally. Dates, spelling, and importance are organized automatically.'} aria-label={singleOwner?`Info dump for ${singleOwner}`:'Info dump'} className="min-h-17 w-full resize-none overflow-hidden rounded-xl border bg-card px-3 py-3 text-sm leading-relaxed outline-none focus:ring-2 focus:ring-ring/30"/><div className="mt-2 flex flex-wrap gap-2"><button onClick={toggleSpeech} disabled={!speechReady} title={speechReady?'Dictate into the info dump':'Speech input is unavailable in this browser'} className={`flex items-center gap-2 rounded-lg border px-3 py-2 text-sm ${listening?'bg-muted':''} disabled:opacity-50`}>{listening?<MicOff className="size-4"/>:<Mic className="size-4"/>}{listening?'Stop listening':'Speak'}</button><button disabled title="Photo extraction is coming soon" className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm text-muted-foreground opacity-60"><ImagePlus className="size-4"/>Photo import · coming soon</button></div>
    {proposal.length>0&&<div className="mt-5 border-t pt-4"><div className="mb-3 flex flex-wrap items-center gap-2"><h3 aria-live="polite" className="mr-auto text-xs font-semibold uppercase tracking-[.14em] text-muted-foreground">Review and approve · {proposal.filter(item=>item.selected).length} selected{singleOwner?` · ${singleOwner}`:''}</h3><button onClick={()=>setProposal(current=>current.map(item=>({...item,selected:true})))} className="rounded-lg border px-2.5 py-1.5 text-xs">Select all</button><button onClick={()=>setProposal(current=>current.map(item=>({...item,selected:false})))} className="rounded-lg border px-2.5 py-1.5 text-xs">Select none</button><button onClick={()=>{setProposal([]);setNotes('')}} className="rounded-lg border px-2.5 py-1.5 text-xs text-muted-foreground">Remove all</button></div><div className="space-y-2">{proposal.map((item,index)=><div key={index} className="grid grid-cols-[auto_minmax(0,1fr)] gap-3 rounded-xl border bg-background p-3"><Checkbox checked={item.selected} onCheckedChange={value=>update(index,{selected:!!value})} aria-label={`Include ${item.title}`} className="mt-2"/><div className="min-w-0"><input aria-label={`Task ${index+1} title`} value={item.title} onChange={e=>update(index,{title:e.target.value})} className="h-9 w-full rounded-lg border bg-card px-3 text-sm"/><div className={`mt-2 grid gap-2 ${singleOwner?'md:grid-cols-[120px_minmax(280px,1fr)_130px]':'md:grid-cols-[120px_150px_minmax(280px,1fr)_130px]'}`}><select aria-label={`Priority for ${item.title}`} value={item.priority} onChange={event=>update(index,{priority:event.target.value as Priority})} className="h-9 rounded-lg border bg-card px-2 text-xs"><option>Low</option><option>Normal</option><option>High</option></select>{!singleOwner&&<select aria-label={`Owner for ${item.title}`} value={item.person} onChange={e=>update(index,{person:e.target.value})} className="h-9 rounded-lg border bg-card px-2 text-xs">{allowedOwners.map(owner=><option key={owner}>{owner}</option>)}</select>}<DateTimeControl label={item.estimatedMinutes>=480?'All-day date':'Schedule'} value={item.scheduledStart} allDay={item.estimatedMinutes>=480} onChange={value=>update(index,{scheduledStart:value})}/><select aria-label={`Repeat for ${item.title}`} value={item.recurrence??'ONCE'} onChange={e=>{const recurring=e.target.value==='WEEKLY';update(index,{recurrence:recurring?'WEEKLY':null,recurrenceDays:recurring?(item.recurrenceDays?.length?item.recurrenceDays:[item.scheduledStart?new Date(item.scheduledStart).getDay():new Date().getDay()]):undefined})}} className="h-9 self-end rounded-lg border bg-card px-2 text-xs"><option value="ONCE">Once</option><option value="WEEKLY">Repeats</option></select></div>{item.recurrence&&<div className="mt-2"><RepeatDays value={item.recurrenceDays} start={item.scheduledStart} onChange={days=>update(index,{recurrenceDays:days})}/></div>}{!item.scheduledStart&&<p className="mt-2 text-xs text-muted-foreground">No date yet · available in Calendar</p>}</div></div>)}</div><div className="mt-4 flex gap-2"><button onClick={addProposal} disabled={!proposal.some(item=>item.selected&&item.title.trim())} className="rounded-lg bg-primary px-4 py-2.5 text-sm text-primary-foreground disabled:opacity-50">Approve selected</button><button onClick={()=>{setProposal([]);setNotes('')}} className="rounded-lg border px-4 py-2.5 text-sm">Clear</button></div></div>}
  </section>;
}

function TaskGroup({section,label,tasks,toggle,edit,remove,showOwner,dragging,onDragStart,onDragEnd,onDrop}:{section:SectionName;label:string;tasks:Task[];toggle:(task:Task)=>void;edit:(task:Task)=>void;remove:(id:string)=>void;showOwner:boolean;dragging:boolean;onDragStart:()=>void;onDragEnd:()=>void;onDrop:(source:SectionName)=>void}){
  const rank:Record<Priority,number>={High:3,Normal:2,Low:1};
  const time=(task:Task)=>{const value=nextTaskDate(task);return value?new Date(value).getTime():Number.MAX_SAFE_INTEGER};
  const ordered=[...tasks].sort((a,b)=>time(a)-time(b)||rank[b.priority]-rank[a.priority]);
  let previousBreak='';
  return <div className={`mb-5 rounded-xl transition ${dragging?'opacity-45 ring-2 ring-ring/30':''}`} onDragOver={event=>{event.preventDefault();event.dataTransfer.dropEffect='move'}} onDrop={event=>{event.preventDefault();const source=event.dataTransfer.getData('text/section-name') as SectionName;if(defaultSectionOrder.includes(source))onDrop(source)}}><div draggable onDragStart={event=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/section-name',section);onDragStart()}} onDragEnd={onDragEnd} className="mb-2 flex min-h-8 cursor-grab items-center gap-1 rounded-lg px-1 hover:bg-muted active:cursor-grabbing" aria-label={`Drag ${label} section`}><GripVertical className="size-4 text-muted-foreground"/><h2 className="mr-auto text-xs font-semibold uppercase tracking-[.14em] text-muted-foreground">{label}</h2><span className="mr-1 text-xs text-muted-foreground">{tasks.length}</span></div><div className="overflow-hidden rounded-xl border bg-card">{ordered.map(task=>{const date=nextTaskDate(task);const currentBreak=label.startsWith('Upcoming')&&date?fmtDate(date):'';const showBreak=!!currentBreak&&currentBreak!==previousBreak;previousBreak=currentBreak;return <div key={task.id}>{showBreak&&<div className="border-b bg-muted/50 px-4 py-1.5 text-[10px] font-semibold uppercase tracking-[.12em] text-muted-foreground">{currentBreak}</div>}<div className="flex min-h-14 items-center gap-3 border-b px-4 last:border-0 hover:bg-muted/60"><Checkbox checked={task.status==='COMPLETED'} onCheckedChange={()=>toggle(task)} className="size-5" aria-label={`${task.status==='TODO'?'Complete':'Reopen'} ${task.title}`}/><button onClick={()=>edit(task)} className="min-w-0 flex-1 py-2.5 text-left"><span className={`block truncate text-sm font-medium ${task.status==='COMPLETED'?'text-muted-foreground line-through':''}`}>{task.title}</span><span className="text-xs text-muted-foreground">{showOwner?`${task.owner} · `:''}{task.source} · {task.estimatedMinutes>=480?'all day':`${task.estimatedMinutes} min`}{task.scheduledStart?` · ${task.recurrence?`repeats ${repeatSummary(task)} · `:''}${fmtTime(task.scheduledStart)}`:''}</span></button><span className={`rounded-full px-2 py-0.5 text-[10px] ${task.priority==='High'?'bg-stone-300 font-semibold':task.priority==='Low'?'bg-muted text-muted-foreground':'border text-muted-foreground'}`}>{task.priority}</span><span className="hidden text-xs tabular-nums text-muted-foreground sm:block">{task.status==='COMPLETED'?fmtTime(task.completedAt):fmtDate(date)}</span>{task.status==='COMPLETED'?<button onClick={()=>remove(task.id)} aria-label={`Delete ${task.title}`} title="Delete completed task" className="rounded-lg p-2 text-muted-foreground hover:bg-muted hover:text-destructive"><Trash2 className="size-4"/></button>:<button onClick={()=>edit(task)} aria-label={`Edit ${task.title}`} className="rounded-lg p-2 text-muted-foreground hover:bg-muted"><MoreHorizontal className="size-4"/></button>}</div></div>})}</div></div>;
}

function TaskEditor({task,allowedOwners,save,remove,close}:{task:Task;allowedOwners:string[];save:(task:Task)=>void;remove:(id:string)=>void;close:()=>void}){const [draft,setDraft]=useState({...task,scheduledStart:task.scheduledStart??task.due}),singleOwner=allowedOwners.length===1;return <div className="fixed inset-0 z-50 grid place-items-center bg-stone-900/25 p-4" onMouseDown={event=>{if(event.currentTarget===event.target)close()}}><section role="dialog" aria-modal="true" aria-labelledby="task-editor-title" className="max-h-[92vh] w-full max-w-2xl overflow-y-auto rounded-2xl border bg-background p-6 shadow-xl"><div className="mb-5 flex items-center"><h2 id="task-editor-title" className="text-xl font-semibold">Task details</h2><button onClick={close} className="ml-auto rounded-lg p-2 hover:bg-muted" aria-label="Close task details"><X className="size-4"/></button></div><label className="mb-5 block text-sm font-medium">Title<input value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} className="mt-1 h-10 w-full rounded-lg border bg-card px-3 font-normal"/></label><div className="grid gap-5 md:grid-cols-2"><div className="space-y-4"><label className="block text-sm font-medium">Duration<select value={draft.estimatedMinutes} onChange={e=>setDraft({...draft,estimatedMinutes:+e.target.value})} className="mt-1 h-10 w-full rounded-lg border bg-card px-3 font-normal"><option value="15">15 minutes</option><option value="30">30 minutes</option><option value="45">45 minutes</option><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option><option value="180">3 hours</option><option value="240">4 hours</option><option value="480">All day</option></select></label><label className="block text-sm font-medium">Priority<select value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value as Priority})} className="mt-1 h-10 w-full rounded-lg border bg-card px-3 font-normal"><option>Low</option><option>Normal</option><option>High</option></select></label>{!singleOwner&&<label className="block text-sm font-medium">Owner<select value={draft.owner} onChange={e=>setDraft({...draft,owner:e.target.value,source:e.target.value==='Alex Advisor'?'Personal':'Advisor'})} className="mt-1 h-10 w-full rounded-lg border bg-card px-3 font-normal">{allowedOwners.map(owner=><option key={owner}>{owner}</option>)}</select></label>}</div><div className="space-y-4"><DateTimeControl label="Schedule" value={draft.scheduledStart} allDay={draft.estimatedMinutes>=480} onChange={value=>setDraft({...draft,scheduledStart:value})}/><label className="block text-sm font-medium">Repeat<select value={draft.recurrence??'ONCE'} onChange={e=>{const recurring=e.target.value==='WEEKLY';setDraft({...draft,recurrence:recurring?'WEEKLY':null,recurrenceDays:recurring?(draft.recurrenceDays?.length?draft.recurrenceDays:[draft.scheduledStart?new Date(draft.scheduledStart).getDay():new Date().getDay()]):undefined,source:recurring?'Recurring':draft.owner==='Alex Advisor'?'Personal':'Advisor'})}} className="mt-1 h-10 w-full rounded-lg border bg-card px-3 font-normal"><option value="ONCE">Once</option><option value="WEEKLY">Repeats</option></select></label>{draft.recurrence&&<div><p className="mb-2 text-sm font-medium">Repeat on</p><RepeatDays value={draft.recurrenceDays} start={draft.scheduledStart} onChange={days=>setDraft({...draft,recurrenceDays:days})}/></div>}</div></div><div className="mt-7 flex items-center gap-2"><button onClick={()=>remove(draft.id)} className="flex items-center gap-2 rounded-lg px-3 py-2 text-sm text-muted-foreground hover:bg-muted"><Trash2 className="size-4"/>Delete</button><button onClick={close} className="ml-auto rounded-lg border px-4 py-2 text-sm">Cancel</button><button onClick={()=>save({...draft,due:draft.scheduledStart})} disabled={!draft.title.trim()} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">Save</button></div></section></div>}

function StudentsView({tasks,open}:{tasks:Task[];open:(name:string)=>void}){return <div className="w-full"><h1 className="text-3xl font-semibold">Students</h1><p className="mt-1 text-sm text-muted-foreground">Each student has a separate task list and calendar.</p><div className="mt-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">{students.map(student=>{const own=tasks.filter(task=>task.owner===student&&task.status==='TODO'),late=own.filter(task=>{const date=nextTaskDate(task);return date&&new Date(date)<new Date()&&!task.recurrence}).length;return <button key={student} onClick={()=>open(student)} className="flex min-h-28 w-full items-center gap-4 rounded-xl border bg-card px-5 text-left hover:bg-muted"><span className="grid size-11 place-items-center rounded-full bg-secondary text-xs font-semibold">{student.split(' ').map(value=>value[0]).join('')}</span><span className="flex-1"><span className="block font-medium">{student}</span><span className="mt-1 block text-sm text-muted-foreground">{own.length?`${own.length} open`:'Clear'}{late?` · ${late} overdue`:''}</span></span><ChevronRight className="size-4 text-muted-foreground"/></button>})}</div></div>}

function CalendarView({tasks,update,edit,create,defaultOwner,allowedOwners}:{tasks:Task[];update:(task:Task)=>void;edit:(task:Task)=>void;create:(task:CalendarTaskDraft)=>void;defaultOwner:string;allowedOwners:string[]}){
  const [mode,setMode]=useState<'day'|'week'|'month'>('week'),[anchor,setAnchor]=useState(new Date()),[placing,setPlacing]=useState<string|null>(null),[quickStart,setQuickStart]=useState<Date|null>(null);
  useEffect(()=>{if(window.matchMedia('(max-width: 767px)').matches)setMode('day')},[]);
  const open=tasks.filter(task=>task.status==='TODO'),unscheduled=open.filter(task=>!task.scheduledStart),scheduled=open.filter(task=>task.scheduledStart),showOwner=allowedOwners.length>1;
  const moveAnchor=(direction:number)=>{const date=new Date(anchor);if(mode==='day')date.setDate(date.getDate()+direction);if(mode==='week')date.setDate(date.getDate()+direction*7);if(mode==='month')date.setMonth(date.getMonth()+direction);setAnchor(date)};
  const moveTask=(id:string,day:Date,hour:number,minute:number,occurrenceDay?:string)=>{const task=tasks.find(item=>item.id===id);if(!task)return;const date=new Date(day);date.setHours(hour,minute,0,0);const scheduledStart=date.toISOString(),plan=recurringMovePlan(task.recurrence,task.recurrenceExceptions,occurrenceDay);if(plan.detach){update({...task,recurrenceExceptions:plan.exceptions});create({title:task.title,owner:task.owner,scheduledStart,estimatedMinutes:task.estimatedMinutes,recurrence:null,recurrenceDays:undefined,priority:task.priority})}else update({...task,scheduledStart,due:task.due?scheduledStart:null});setPlacing(null)};
  const moveTaskDay=(id:string,day:Date,occurrenceDay?:string)=>{const task=tasks.find(item=>item.id===id);if(!task)return;const previous=task.scheduledStart?new Date(task.scheduledStart):null;moveTask(id,day,previous?.getHours()??9,previous?.getMinutes()??0,occurrenceDay)};
  const activate=(day:Date,hour:number,minute:number)=>{if(placing){moveTask(placing,day,hour,minute);return}const date=new Date(day);date.setHours(hour,minute,0,0);setQuickStart(date)};
  const weekStart=startOfWeek(anchor), weekDays=Array.from({length:7},(_,index)=>{const date=new Date(weekStart);date.setDate(date.getDate()+index);return date});
  const slots=Array.from({length:22},(_,index)=>({hour:8+Math.floor(index/2),minute:index%2?30:0}));
  const label=mode==='month'?new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(anchor):mode==='day'?new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(anchor):`${fmtDate(weekDays[0].toISOString())} – ${fmtDate(weekDays[6].toISOString())}`;
  return <div className="w-full"><div className="grid gap-3 sm:flex sm:flex-wrap sm:items-end"><div className="sm:mr-auto"><h1 className="text-2xl font-semibold">Calendar</h1><p className="text-sm text-muted-foreground">{label}</p></div><div className="grid grid-cols-3 rounded-lg border bg-card p-1 sm:flex">{(['day','week','month'] as const).map(item=><button key={item} onClick={()=>setMode(item)} className={`min-h-10 rounded-md px-3 py-1.5 text-sm capitalize sm:min-h-0 sm:text-xs ${mode===item?'bg-primary text-primary-foreground':'text-muted-foreground hover:bg-muted'}`}>{item}</button>)}</div><div className="grid grid-cols-[44px_1fr_44px] gap-2 sm:flex"><button onClick={()=>moveAnchor(-1)} aria-label={`Previous ${mode}`} className="grid min-h-11 place-items-center rounded-lg border"><ChevronLeft className="size-4"/></button><button onClick={()=>setAnchor(new Date())} className="min-h-11 rounded-lg border px-3 text-sm sm:min-h-0 sm:py-2">Today</button><button onClick={()=>moveAnchor(1)} aria-label={`Next ${mode}`} className="grid min-h-11 place-items-center rounded-lg border"><ChevronRight className="size-4"/></button></div></div>
    <p className="mt-2 text-xs text-muted-foreground"><span className="md:hidden">Tap a time to add. Tap a task to edit it.</span><span className="hidden md:inline">Click anywhere to add. Drag tasks to move them.</span></p><div className={`mt-2 grid items-stretch gap-3 ${unscheduled.length?'xl:grid-cols-[210px_minmax(0,1fr)]':''}`}>{unscheduled.length>0&&<aside className="rounded-xl border bg-card p-3"><div className="mb-2 flex items-center justify-between"><h2 className="text-sm font-semibold">Unscheduled</h2><span className="text-xs text-muted-foreground">{unscheduled.length}</span></div><div className="space-y-2">{unscheduled.map(task=><button key={task.id} draggable onDragStart={event=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/task-id',task.id)}} onClick={()=>setPlacing(placing===task.id?null:task.id)} className={`flex min-h-11 w-full items-start gap-2 rounded-lg border p-2 text-left text-xs ${placing===task.id?'border-primary bg-muted ring-2 ring-ring/20':'hover:bg-muted'}`}><GripVertical className="mt-0.5 size-3 shrink-0 text-muted-foreground"/><span><span className="block font-medium">{task.title}</span>{showOwner&&<span className="text-muted-foreground">{task.owner}</span>}</span></button>)}</div></aside>}
      {mode==='month'?<MonthGrid anchor={anchor} tasks={scheduled} moveDay={moveTaskDay} activate={day=>activate(day,9,0)} edit={edit}/>:<TimeGrid days={mode==='day'?[anchor]:weekDays} slots={slots} tasks={scheduled} activate={activate} move={moveTask} edit={edit} showOwner={showOwner}/>}
    </div>{placing&&<p className="mt-2 rounded-lg bg-muted px-3 py-2 text-sm">Choose a time for <b>{tasks.find(task=>task.id===placing)?.title}</b>.</p>}{quickStart&&<QuickCalendarAdd start={quickStart} defaultOwner={defaultOwner} allowedOwners={allowedOwners} close={()=>setQuickStart(null)} create={draft=>{create(draft);setQuickStart(null)}}/>}</div>;
}

function TimeGrid({days,slots,tasks,activate,move,edit,showOwner}:{days:Date[];slots:{hour:number;minute:number}[];tasks:Task[];activate:(day:Date,hour:number,minute:number)=>void;move:(id:string,day:Date,hour:number,minute:number,occurrenceDay?:string)=>void;edit:(task:Task)=>void;showOwner:boolean}){
  const label=(hour:number,minute:number)=>new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(2026,0,1,hour,minute));
  const startIndex=(task:Task)=>{if(!task.scheduledStart)return -1;const value=new Date(task.scheduledStart);return (value.getHours()-slots[0].hour)*2+(value.getMinutes()>=30?1:0)};
  const readDrop=(event:React.DragEvent)=>({id:event.dataTransfer.getData('text/task-id'),occurrence:event.dataTransfer.getData('text/task-occurrence')||undefined});
  const writeDrag=(event:React.DragEvent,task:Task,day:Date)=>{event.stopPropagation();event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/task-id',task.id);event.dataTransfer.setData('text/task-occurrence',dayKey(day))};
  const gridWidth=days.length>1?'min-w-[720px]':'';
  const sortTasks=(items:Task[])=>[...items].sort((a,b)=>(a.scheduledStart??'').localeCompare(b.scheduledStart??''));
  const mobileDay=days.length===1;
  return <><div className="md:hidden">{mobileDay?<div className="overflow-hidden rounded-xl border bg-card">
    {tasks.some(task=>task.estimatedMinutes>=480&&occursOn(task,days[0]))&&<div className="grid grid-cols-[64px_1fr] border-b bg-muted/30"><div className="px-2 py-3 text-right text-[11px] font-medium text-muted-foreground">All day</div><div className="space-y-1 border-l p-2">{sortTasks(tasks.filter(task=>task.estimatedMinutes>=480&&occursOn(task,days[0]))).map(task=><button key={task.id} onClick={()=>edit(task)} className="block min-h-11 w-full rounded-lg border bg-background px-3 py-2 text-left"><span className="block text-sm font-medium">{task.title}</span>{showOwner&&<span className="block text-xs text-muted-foreground">{task.owner}</span>}</button>)}</div></div>}
    {slots.map(slot=>{const items=sortTasks(tasks.filter(task=>task.estimatedMinutes<480&&occursOn(task,days[0])&&startIndex(task)===slots.indexOf(slot)));return <div key={`${slot.hour}:${slot.minute}`} className="grid min-h-14 grid-cols-[64px_1fr] border-b last:border-0"><button onClick={()=>activate(days[0],slot.hour,slot.minute)} className="px-2 text-right text-[11px] tabular-nums text-muted-foreground hover:bg-muted">{label(slot.hour,slot.minute)}</button><div className="border-l p-1.5">{items.length?<div className="space-y-1">{items.map(task=><button key={task.id} onClick={()=>edit(task)} className="block min-h-11 w-full rounded-lg border border-stone-300 bg-stone-100 px-3 py-2 text-left"><span className="block text-sm font-semibold">{task.title}</span><span className="block text-xs text-muted-foreground">{timeRange(task.scheduledStart,task.estimatedMinutes)}{showOwner?` · ${task.owner}`:''}</span></button>)}</div>:<button onClick={()=>activate(days[0],slot.hour,slot.minute)} aria-label={`Add at ${label(slot.hour,slot.minute)}`} className="min-h-10 w-full rounded-lg text-left text-xs text-muted-foreground/70 hover:bg-muted hover:px-2">Tap to add</button>}</div></div>})}
  </div>:<div className="space-y-3">{days.map(day=>{const items=sortTasks(tasks.filter(task=>occursOn(task,day)));return <section key={day.toISOString()} className={`overflow-hidden rounded-xl border bg-card ${sameDay(day,new Date())?'ring-2 ring-ring/20':''}`}><button onClick={()=>activate(day,9,0)} className="flex min-h-12 w-full items-center border-b bg-muted/35 px-3 text-left"><span className="font-semibold">{new Intl.DateTimeFormat(undefined,{weekday:'long'}).format(day)}</span><span className="ml-2 text-sm text-muted-foreground">{new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(day)}</span><span className="ml-auto text-xs text-muted-foreground">+ Add</span></button>{items.length?<div className="divide-y">{items.map(task=><button key={task.id} onClick={()=>edit(task)} className="flex min-h-14 w-full items-center gap-3 px-3 py-2 text-left hover:bg-muted"><span className="w-16 shrink-0 text-xs tabular-nums text-muted-foreground">{task.estimatedMinutes>=480?'All day':fmtTime(task.scheduledStart)}</span><span className="min-w-0"><span className="block truncate text-sm font-medium">{task.title}</span><span className="block truncate text-xs text-muted-foreground">{task.estimatedMinutes>=480?'All day':timeRange(task.scheduledStart,task.estimatedMinutes)}{showOwner?` · ${task.owner}`:''}</span></span></button>)}</div>:<button onClick={()=>activate(day,9,0)} className="min-h-12 w-full px-3 text-left text-sm text-muted-foreground">Nothing scheduled · tap to add</button>}</section>})}</div>}</div><div className="hidden h-[calc(100vh-176px)] min-h-[560px] overflow-x-auto overflow-y-hidden rounded-xl border bg-card md:block"><div className={`flex h-full flex-col ${gridWidth}`}>
    <div className="grid h-10 shrink-0" style={{gridTemplateColumns:`76px repeat(${days.length},minmax(88px,1fr))`}}><div/>{days.map(day=><button key={day.toISOString()} onClick={()=>activate(day,9,0)} className={`border-l border-b text-center hover:bg-muted ${sameDay(day,new Date())?'bg-muted':''}`}><span className="mr-1 text-[10px] uppercase text-muted-foreground">{new Intl.DateTimeFormat(undefined,{weekday:'short'}).format(day)}</span><span className="text-sm font-semibold">{day.getDate()}</span></button>)}</div>
    <div className="grid min-h-9 shrink-0" style={{gridTemplateColumns:`76px repeat(${days.length},minmax(88px,1fr))`}}><div className="border-b pr-2 pt-2 text-right text-[10px] text-muted-foreground">All day</div>{days.map(day=>{const items=tasks.filter(task=>task.estimatedMinutes>=480&&occursOn(task,day));return <div key={day.toISOString()} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();const drop=readDrop(event);if(drop.id)move(drop.id,day,9,0,drop.occurrence)}} className="flex min-w-0 gap-1 border-l border-b p-1">{items.map(task=><button key={task.id} draggable onDragStart={event=>writeDrag(event,task,day)} onClick={()=>edit(task)} className="min-w-0 flex-1 cursor-grab truncate rounded border bg-stone-100 px-1.5 py-0.5 text-left text-[9px] active:cursor-grabbing" title={`${task.title} · All day`}>{task.title}</button>)}</div>})}</div>
      <div className="grid min-h-0 flex-1" style={{gridTemplateColumns:`76px repeat(${days.length},minmax(88px,1fr))`}}><div className="grid h-full" style={{gridTemplateRows:`repeat(${slots.length},minmax(0,1fr))`}}>{slots.map(slot=><button key={`${slot.hour}:${slot.minute}`} onClick={()=>activate(days.find(day=>sameDay(day,new Date()))??days[0],slot.hour,slot.minute)} className="border-b pr-2 text-right text-[10px] tabular-nums text-muted-foreground hover:bg-muted">{label(slot.hour,slot.minute)}</button>)}</div>{days.map(day=>{const items=tasks.filter(task=>task.estimatedMinutes<480&&occursOn(task,day)&&startIndex(task)>=0&&startIndex(task)<slots.length);return <div key={day.toISOString()} className="relative min-h-0 border-l">{slots.map((slot,index)=><button key={`${slot.hour}:${slot.minute}`} onClick={()=>activate(day,slot.hour,slot.minute)} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();event.stopPropagation();const drop=readDrop(event);if(drop.id)move(drop.id,day,slot.hour,slot.minute,drop.occurrence)}} aria-label={`${label(slot.hour,slot.minute)} on ${fmtDate(day.toISOString())}`} className="absolute left-0 w-full cursor-pointer border-b hover:bg-muted" style={{top:`${index/slots.length*100}%`,height:`${100/slots.length}%`}}/>)}{items.map(task=>{const index=startIndex(task),sameStart=items.filter(item=>startIndex(item)===index),position=sameStart.findIndex(item=>item.id===task.id),span=Math.min(Math.max(1,Math.ceil(task.estimatedMinutes/30)),slots.length-index);return <button key={task.id} draggable onDragStart={event=>writeDrag(event,task,day)} onClick={event=>{event.stopPropagation();edit(task)}} title={`${task.title}${showOwner?` · ${task.owner}`:''} · ${timeRange(task.scheduledStart,task.estimatedMinutes)}`} className="absolute z-10 flex min-w-0 cursor-grab flex-col overflow-hidden rounded border border-stone-300 bg-stone-100 px-1 py-0.5 text-left text-[9px] shadow-sm active:cursor-grabbing" style={{top:`calc(${index/slots.length*100}% + 1px)`,height:`calc(${span/slots.length*100}% - 2px)`,minHeight:'18px',left:`calc(${position/sameStart.length*100}% + 2px)`,width:`calc(${100/sameStart.length}% - 4px)`}}><span className="flex items-center gap-0.5"><GripVertical className="size-2.5 shrink-0 text-muted-foreground"/><b className="truncate">{task.title}</b></span><span className="truncate text-[8px] text-muted-foreground">{timeRange(task.scheduledStart,task.estimatedMinutes)}</span></button>})}</div>})}</div>
  </div></div></>;
}

function MonthGrid({anchor,tasks,moveDay,activate,edit}:{anchor:Date;tasks:Task[];moveDay:(id:string,day:Date,occurrenceDay?:string)=>void;activate:(day:Date)=>void;edit:(task:Task)=>void}){const first=new Date(anchor.getFullYear(),anchor.getMonth(),1),start=startOfWeek(first),days=Array.from({length:42},(_,index)=>{const date=new Date(start);date.setDate(date.getDate()+index);return date});const [selected,setSelected]=useState(()=>sameDay(anchor,new Date())?new Date():first);useEffect(()=>setSelected(sameDay(anchor,new Date())?new Date():new Date(anchor.getFullYear(),anchor.getMonth(),1)),[anchor]);const selectedTasks=[...tasks.filter(task=>occursOn(task,selected))].sort((a,b)=>(a.scheduledStart??'').localeCompare(b.scheduledStart??''));return <><div className="md:hidden"><div className="overflow-hidden rounded-xl border bg-card"><div className="grid grid-cols-7 border-b bg-muted/40">{['M','T','W','T','F','S','S'].map((value,index)=><div key={`${value}-${index}`} className="py-2 text-center text-[11px] font-semibold text-muted-foreground">{value}</div>)}</div><div className="grid grid-cols-7">{days.map(day=>{const count=tasks.filter(task=>occursOn(task,day)).length;const active=sameDay(day,selected);return <button key={day.toISOString()} onClick={()=>setSelected(day)} aria-label={`${fmtDate(day.toISOString())}${count?`, ${count} task${count===1?'':'s'}`:''}`} className={`relative min-h-12 border-r border-b p-1 text-sm ${day.getMonth()!==anchor.getMonth()?'text-muted-foreground/40':''} ${active?'bg-muted ring-2 ring-inset ring-primary/40':''}`}><span className={sameDay(day,new Date())?'rounded-full bg-primary px-1.5 py-0.5 text-primary-foreground':''}>{day.getDate()}</span>{count>0&&<span className="absolute bottom-1 left-1/2 size-1.5 -translate-x-1/2 rounded-full bg-primary"/>}</button>})}</div></div><section className="mt-3 overflow-hidden rounded-xl border bg-card"><div className="flex min-h-12 items-center border-b bg-muted/35 px-3"><span className="font-semibold">{new Intl.DateTimeFormat(undefined,{weekday:'long',month:'short',day:'numeric'}).format(selected)}</span><button onClick={()=>activate(selected)} className="ml-auto rounded-lg border bg-background px-3 py-1.5 text-xs">+ Add</button></div>{selectedTasks.length?<div className="divide-y">{selectedTasks.map(task=><button key={task.id} onClick={()=>edit(task)} className="flex min-h-14 w-full items-center gap-3 px-3 py-2 text-left"><span className="w-16 shrink-0 text-xs tabular-nums text-muted-foreground">{task.estimatedMinutes>=480?'All day':fmtTime(task.scheduledStart)}</span><span className="min-w-0 truncate text-sm font-medium">{task.title}</span></button>)}</div>:<button onClick={()=>activate(selected)} className="min-h-14 w-full px-3 text-left text-sm text-muted-foreground">Nothing scheduled · tap to add</button>}</section></div><div className="hidden h-[calc(100vh-176px)] min-h-[560px] overflow-hidden rounded-xl border bg-card md:block"><div className="grid h-8 grid-cols-7 border-b bg-muted/40">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(value=><div key={value} className="p-1.5 text-center text-xs font-medium text-muted-foreground">{value}</div>)}</div><div className="grid grid-cols-7 grid-rows-6" style={{height:'calc(100% - 32px)'}}>{days.map(day=>{const items=tasks.filter(task=>occursOn(task,day));return <div key={day.toISOString()} onClick={()=>activate(day)} onDragOver={event=>event.preventDefault()} onDrop={event=>{event.preventDefault();const id=event.dataTransfer.getData('text/task-id'),occurrence=event.dataTransfer.getData('text/task-occurrence')||undefined;if(id)moveDay(id,day,occurrence)}} className={`min-h-0 cursor-pointer border-r border-b p-1.5 hover:bg-muted/60 ${day.getMonth()!==anchor.getMonth()?'text-muted-foreground/50':''}`}><span className={`text-xs ${sameDay(day,new Date())?'rounded-full bg-primary px-2 py-1 text-primary-foreground':''}`}>{day.getDate()}</span>{items.slice(0,3).map(task=><button key={task.id} draggable onDragStart={event=>{event.stopPropagation();event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/task-id',task.id);event.dataTransfer.setData('text/task-occurrence',dayKey(day))}} onClick={event=>{event.stopPropagation();edit(task)}} className="mt-1 block w-full cursor-grab truncate rounded bg-muted px-1.5 py-0.5 text-left text-[10px] active:cursor-grabbing">{task.estimatedMinutes>=480?'All day':fmtTime(task.scheduledStart)} {task.title}</button>)}</div>})}</div></div></>}

function QuickCalendarAdd({start,defaultOwner,allowedOwners,close,create}:{start:Date;defaultOwner:string;allowedOwners:string[];close:()=>void;create:(task:CalendarTaskDraft)=>void}){const [title,setTitle]=useState(''),[owner,setOwner]=useState(defaultOwner),[duration,setDuration]=useState(30),[recurrence,setRecurrence]=useState<'WEEKLY'|null>(null),[recurrenceDays,setRecurrenceDays]=useState<number[]|undefined>(),[priority,setPriority]=useState<Priority>('Normal'),[schedule,setSchedule]=useState<string|null>(start.toISOString()),singleOwner=allowedOwners.length===1;const submit=()=>{if(!title.trim()||!schedule)return;create({title:title.trim(),owner,scheduledStart:schedule,estimatedMinutes:duration,recurrence,recurrenceDays,priority})};return <div className="fixed inset-0 z-50 grid place-items-center bg-stone-900/25 p-4" onMouseDown={event=>{if(event.currentTarget===event.target)close()}}><section role="dialog" aria-modal="true" aria-labelledby="quick-calendar-title" className="max-h-[92vh] w-full max-w-xl overflow-y-auto rounded-2xl border bg-background p-5 shadow-xl"><div className="mb-4 flex items-center"><div><h2 id="quick-calendar-title" className="text-lg font-semibold">Quick add</h2><p className="text-sm text-muted-foreground">Adjust anything before adding.</p></div><button onClick={close} className="ml-auto rounded-lg p-2 hover:bg-muted" aria-label="Close quick add"><X className="size-4"/></button></div><input autoFocus value={title} onChange={event=>setTitle(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')submit()}} placeholder="Task or appointment" className="h-11 w-full rounded-lg border bg-card px-3 text-sm"/><div className="mt-3"><DateTimeControl label={duration>=480?'All-day date':'Schedule'} value={schedule} allDay={duration>=480} onChange={setSchedule}/></div><div className={`mt-3 grid grid-cols-2 gap-2 ${singleOwner?'sm:grid-cols-3':'sm:grid-cols-4'}`}>{!singleOwner&&<select aria-label="Task owner" value={owner} onChange={event=>setOwner(event.target.value)} className="h-10 rounded-lg border bg-card px-2 text-sm">{allowedOwners.map(person=><option key={person}>{person}</option>)}</select>}<select aria-label="Duration" value={duration} onChange={event=>setDuration(Number(event.target.value))} className="h-10 rounded-lg border bg-card px-2 text-sm"><option value="15">15 min</option><option value="30">30 min</option><option value="45">45 min</option><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option><option value="180">3 hours</option><option value="240">4 hours</option><option value="480">All day</option></select><select aria-label="Priority" value={priority} onChange={event=>setPriority(event.target.value as Priority)} className="h-10 rounded-lg border bg-card px-2 text-sm"><option>Low</option><option>Normal</option><option>High</option></select><select aria-label="Repeat" value={recurrence??'ONCE'} onChange={event=>{const recurring=event.target.value==='WEEKLY';setRecurrence(recurring?'WEEKLY':null);setRecurrenceDays(recurring?(recurrenceDays?.length?recurrenceDays:[schedule?new Date(schedule).getDay():new Date().getDay()]):undefined)}} className="h-10 rounded-lg border bg-card px-2 text-sm"><option value="ONCE">Once</option><option value="WEEKLY">Repeats</option></select></div>{recurrence&&<div className="mt-3"><p className="mb-2 text-sm font-medium">Repeat on</p><RepeatDays value={recurrenceDays} start={schedule} onChange={setRecurrenceDays}/></div>}<div className="mt-4 flex justify-end gap-2"><button onClick={close} className="rounded-lg border px-4 py-2 text-sm">Cancel</button><button onClick={submit} disabled={!title.trim()||!schedule} className="rounded-lg bg-primary px-4 py-2 text-sm text-primary-foreground disabled:opacity-50">Add to tasks + calendar</button></div></section></div>}

function SettingsView({lastSync,sync,tasks}:{lastSync:string;sync:()=>void;tasks:Task[]}){return <div className="w-full"><h1 className="text-3xl font-semibold">Settings</h1><p className="mt-1 text-sm text-muted-foreground">Core tasks remain available when integrations are offline.</p><div className="mt-5 grid gap-4 md:grid-cols-2 xl:grid-cols-3">{['Canvas','Microsoft Outlook','Copilot bridge'].map((name,index)=><div key={name} className="flex min-h-32 items-center gap-4 rounded-xl border bg-card p-5"><div className="flex-1"><p className="font-medium">{name}</p><p className="text-sm text-muted-foreground">{index===2?'Disabled · local organizer available':'Mock provider · '+lastSync}</p></div><button onClick={sync} className="flex items-center gap-2 rounded-lg border px-3 py-2 text-sm"><RefreshCw className="size-4"/>Sync now</button></div>)}<button onClick={()=>{const blob=new Blob([JSON.stringify({version:6,tasks},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='torgy-backup.json';link.click()}} className="flex min-h-28 items-center justify-center gap-2 rounded-xl border bg-card px-4 py-3 text-sm"><Download className="size-4"/>Export JSON backup</button><div className="min-h-28 rounded-xl border bg-card p-5"><p className="font-medium">Keyboard shortcut</p><p className="mt-1 text-sm text-muted-foreground">Ctrl/⌘ N focuses the info dump.</p></div></div></div>}
